BASE_DISCOUNTS = {
    'student': 0.2,
    'senior': 0.15,
    'regular': 0.0,
}

MEMBER_MODIFIERS = {
    'student': 0.05,
    'senior': 0.05,
    'regular': 0.1,
}

LOYALTY_MODIFIERS = {
    'student': 0.05,
    'senior': 0.05,
    'regular': 0.05,
}


def calculate_discount(price, user_type, is_member, years_active):
    discount = BASE_DISCOUNTS.get(user_type, 0)
    if is_member:
        discount += MEMBER_MODIFIERS.get(user_type, 0)
        if years_active > 5:
            discount += LOYALTY_MODIFIERS.get(user_type, 0)
    return price * (1 - discount)
